To ensure the calculator remains extensible, we use a design that encapsulates history management and operation logic. By using internal state (`self._history`), we allow future memory features to coexist without polluting the arithmetic logic.

### 1. `operations.py`
This class is designed as the core engine. Future operations (like `power` or `modulo`) can be added by appending new methods, and the `_record` helper ensures uniform history tracking.

```python
from typing import List, Tuple, Union

class Calculator:
    def __init__(self):
        self._history: List[Tuple[str, float, float, float]] = []

    def _record(self, op: str, a: float, b: float, result: float):
        self._history.append((op, a, b, result))
        return result

    def add(self, a: float, b: float) -> float:
        return self._record("add", a, b, a + b)

    def subtract(self, a: float, b: float) -> float:
        return self._record("subtract", a, b, a - b)

    def multiply(self, a: float, b: float) -> float:
        return self._record("multiply", a, b, a * b)

    def divide(self, a: float, b: float) -> float:
        if b == 0:
            raise ValueError("Cannot divide by zero.")
        return self._record("divide", a, b, a / b)

    def get_history(self) -> List[Tuple[str, float, float, float]]:
        return self._history

    def clear_history(self) -> None:
        self._history = []
```

### 2. `main.py`
We use `argparse` to map CLI flags to class methods. This structure allows easy addition of new `--op` choices later.

```python
import argparse
from operations import Calculator

def main():
    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument("--op", choices=['add', 'subtract', 'multiply', 'divide'], required=True)
    parser.add_argument("a", type=float)
    parser.add_argument("b", type=float)

    args = parser.parse_args()
    calc = Calculator()

    try:
        func = getattr(calc, args.op)
        result = func(args.a, args.b)
        print(f"Result: {result}")
        print(f"History: {calc.get_history()}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
```

### 3. `test_calc.py`
Using `pytest`, we verify the state management alongside the arithmetic.

```python
import pytest
from operations import Calculator

@pytest.fixture
def calc():
    return Calculator()

def test_basic_ops(calc):
    assert calc.add(2, 3) == 5
    assert calc.subtract(5, 2) == 3
    assert calc.multiply(2, 4) == 8
    assert calc.divide(10, 2) == 5

def test_divide_by_zero(calc):
    with pytest.raises(ValueError, match="Cannot divide by zero"):
        calc.divide(10, 0)

def test_history(calc):
    calc.add(1, 1)
    calc.multiply(2, 2)
    assert len(calc.get_history()) == 2
    calc.clear_history()
    assert len(calc.get_history()) == 0
